    expect(validateClaimAmount({ ...p, input: '0.0004' })).toEqual({ ok: false, error: 'RECEIVE_NOT_POSITIVE' });
    expect(validateClaimAmount({ ...p, input: '0.00050001' }).ok).toBe(true);
  });

