window.__calls = [];
let polls = 0;
const created = new Date().toISOString();
const res = (status, body) => new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });
window.fetch = async (url, init = {}) => {
  const u = new URL(url);
  window.__calls.push([init.method || 'GET', u.pathname]);
  if (u.pathname === '/v1/balances') return res(200, { asOf: new Date(Date.now() - 3000).toISOString(), items: [{ asset: 'BTC', decimals: 8, available: '1', pending: '0', claiming: '0', usdPrice: '100' }] });
  if (u.pathname === '/v1/claim-options') return res(200, { asset: 'BTC', minAmount: '0.001', fee: '0.0005', destinations: [{ id: 'd1', label: 'Wallet' }] });
  if (u.pathname === '/v1/claims' && init.method === 'POST') return res(201, { id: 'clm_9', ...JSON.parse(init.body), fee: '0.0005', receiveAmount: '0.0995', status: 'pending', failureReason: null, createdAt: created, updatedAt: created });
  if (u.pathname === '/v1/claims/clm_9') { polls++; return res(200, { id: 'clm_9', asset: 'BTC', amount: '0.1', fee: '0.0005', receiveAmount: '0.0995', destinationId: 'd1', status: polls > 3 ? 'completed' : 'pending', failureReason: null, createdAt: created, updatedAt: polls > 3 ? new Date().toISOString() : created }); }
  return res(404, { error: { code: 'NOT_FOUND', message: 'nf' } });
};
